#!/usr/bin/env node
/**
 * Backfill the GA4 gtag snippet into every prerendered HTML file under
 * /public that's missing it.
 *
 * Why this exists
 * ---------------
 * 28,069 of 47,036 prerendered HTML files were generated by earlier
 * runs of scripts/generate-*.mjs that didn't include the gtag snippet
 * (predating the May 14 GA4 cleanup commit). All the current
 * generators DO emit the snippet, but the stale files were never
 * regenerated. Result: crawler hits + direct .html hits on those
 * pages weren't tracked, undercounting the platform's total visitor
 * count in GA4.
 *
 * This script is idempotent and safe to run on every Vercel deploy:
 * it skips files that already contain the GA tag, so re-runs are a
 * no-op.
 *
 * Approach
 * --------
 * For each *.html under public/:
 *   - Skip if it already contains `googletagmanager.com/gtag/js`.
 *   - Find the closing </head> tag.
 *   - Insert the gtag snippet from scripts/_ga.mjs immediately before
 *     it. send_page_view stays at its default (true) — these pages
 *     are static HTML and never bootstrap React, so RouteChangeTracker
 *     never fires and the auto page_view is the only one we get.
 *
 * Wired into package.json `build:vercel` so every deploy refreshes
 * any stragglers.
 */

import { readFileSync, readdirSync, writeFileSync } from "node:fs";
import { join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { gtagSnippet } from "./_ga.mjs";

const __dirname = fileURLToPath(new URL(".", import.meta.url));
const ROOT = resolve(__dirname, "..");
const PUBLIC_DIR = join(ROOT, "public");

const SNIPPET = gtagSnippet();
const SNIPPET_BLOCK = `  <!-- Google Analytics 4 — backfilled by scripts/backfill-ga-snippet.mjs -->\n${SNIPPET}\n`;

function listHtml(dir) {
  const out = [];
  for (const name of readdirSync(dir, { withFileTypes: true })) {
    const full = join(dir, name.name);
    if (name.isDirectory()) out.push(...listHtml(full));
    else if (name.name.endsWith(".html")) out.push(full);
  }
  return out;
}

const files = listHtml(PUBLIC_DIR);
console.log(`\n🔍 Scanning ${files.length} prerendered HTML files for missing GA snippet…\n`);

let patched = 0;
let alreadyOk = 0;
let skipped = 0;
const skippedFiles = [];

for (const file of files) {
  const html = readFileSync(file, "utf8");
  // Already has gtag? Skip — generators emit it for newly built files.
  if (html.includes("googletagmanager.com/gtag/js")) {
    alreadyOk++;
    continue;
  }
  // No closing </head>? Malformed file — skip and report.
  if (!html.includes("</head>")) {
    skipped++;
    skippedFiles.push(file);
    continue;
  }
  const patchedHtml = html.replace("</head>", `${SNIPPET_BLOCK}</head>`);
  writeFileSync(file, patchedHtml);
  patched++;
}

console.log(`✅ Patched:        ${patched}`);
console.log(`⏭  Already had GA: ${alreadyOk}`);
if (skipped > 0) {
  console.log(`⚠  Skipped (no </head>): ${skipped}`);
  for (const f of skippedFiles.slice(0, 5)) console.log(`     ${f}`);
  if (skippedFiles.length > 5) console.log(`     …and ${skippedFiles.length - 5} more`);
}
console.log("");
